INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application/phase-workflow-runner', 'community', 'UBAIDRAZA1', 'UBAIDRAZA1-Todo-Web-Application', 'UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application', 'phase-workflow-runner', 0, 0, 55, '2026-02-18T01:08:43.536Z', '2026-02-18T15:52:16.144Z', NULL, '{"id":"UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application/phase-workflow-runner","name":"phase-workflow-runner","description":{"en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"seo":{"title":{"en":"phase-workflow-runner"},"description":{"en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"definition":{"en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"features":{"en":[]},"keywords":{"en":[]}},"owner":"UBAIDRAZA1","repo":"UBAIDRAZA1-Todo-Web-Application","repoPath":"UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.536Z","topics":[],"category":"community","skillMd":{"name":"phase-workflow-runner","description":"Runs a complete phase workflow: audit existing work, fill gaps, run tests, verify acceptance criteria, and report readiness for next phase. Use when user asks to run or complete a project phase.","bodyPreview":"# Phase Workflow Runner\n\nThis skill executes a deterministic, repeatable phase workflow.\n\n## Core Principles\n- Never overwrite existing working code\n- Never redo completed tasks\n- Always audit before action\n- Tests define correctness\n- Phase completion requires verification\n\n## Workflow Steps (MANDATORY)\n\n### 1. Phase Audit\n- Inspect project structure\n- Read relevant spec and tasks files\n- Identify:\n  - Completed items\n  - Missing files\n  - Failing or absent tests\n  - Partial implementations\n\nPr","body":"# Phase Workflow Runner\n\nThis skill executes a deterministic, repeatable phase workflow.\n\n## Core Principles\n- Never overwrite existing working code\n- Never redo completed tasks\n- Always audit before action\n- Tests define correctness\n- Phase completion requires verification\n\n## Workflow Steps (MANDATORY)\n\n### 1. Phase Audit\n- Inspect project structure\n- Read relevant spec and tasks files\n- Identify:\n  - Completed items\n  - Missing files\n  - Failing or absent tests\n  - Partial implementations\n\nProduce a concise audit report before proceeding.\n\n### 2. Gap Filling\nOnly after audit:\n- Create missing source files\n- Create missing test files (RED)\n- Implement minimal code to pass tests (GREEN)\n- Refactor if required\n\nRules:\n- Do not modify completed, passing code\n- Do not remove existing functionality\n\n### 3. Execution & Verification\n- Run full test suite\n- Perform manual smoke checks if CLI/project requires\n- Verify acceptance criteria from spec.md\n\n### 4. Documentation Update\n- Update tasks.md checkboxes\n- Mark checkpoints complete\n- Add short completion summary\n\n### 5. Completion Gate\nIf all criteria pass:\n- Declare phase COMPLETE\n- Ask user:\n  “Phase X complete. Proceed to Phase X+1?”\n\nIf not:\n- Report blockers and stop\n\n## Safety Rules\n- Never hallucinate missing work\n- Never assume tests exist\n- Never skip audit\n- Never continue if tests fail\n\n## Output Format\nAlways output:\n1. Audit Summary\n2. Actions Taken\n3. Test Results\n4. Acceptance Criteria Status\n5. Next Step Recommendation\n"},"lastSynced":"2026-02-18T15:52:16.144Z","qualityScore":55}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application/session-state-manager', 'community', 'UBAIDRAZA1', 'UBAIDRAZA1-Todo-Web-Application', 'UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application', 'session-state-manager', 0, 0, 50, '2026-02-18T01:08:43.536Z', '2026-02-18T15:59:18.853Z', NULL, '{"id":"UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application/session-state-manager","name":"session-state-manager","description":{"zh":"会话状态管理器是一种自动保存会话状态的技能，防止上下文丢失，适用于Full-Stack开发","ja":"セッションステートマネージャーは、セッション状態を自動保存するスキルで、コンテキストの喪失を防ぎ、Full-Stack開発に適しています","ko":"세션 상태 관리자는 세션 상태를 자동으로 저장하는 기술로 컨텍스트 손실을 방지하고 Full-Stack 개발에 적합합니다","en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"seo":{"title":{"zh":"会话状态管理器 - 保持上下文","ja":"セッションステートマネージャー - コンテキストを維持","ko":"세션 상태 관리자 - 컨텍스트 유지","en":"session-state-manager"},"description":{"zh":"会话状态管理器是一种自动保存会话状态的技能，防止上下文丢失，适用于Full-Stack开发","ja":"セッションステートマネージャーは、セッション状態を自動保存するスキルで、コンテキストの喪失を防ぎ、Full-Stack開発に適しています","ko":"세션 상태 관리자는 세션 상태를 자동으로 저장하는 기술로 컨텍스트 손실을 방지하고 Full-Stack 개발에 적합합니다","en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"definition":{"en":"Hackathon ll phase 2 Full-Stack Todo Web Application"},"features":{"zh":["自动保存会话状态","防止上下文丢失","支持Full-Stack开发","持续保存重要交互","自动触发保存","维持开发体验的连续性"],"ja":["セッション状態を自動保存","コンテキストの喪失を防ぐ","Full-Stack開発をサポート","重要なインタラクションを継続して保存","自動で保存をトリガー","開発体験の連続性を維持"],"ko":["세션 상태를 자동으로 저장","컨텍스트 손실을 방지","Full-Stack 개발을 지원","중요한 상호작용을 지속적으로 저장","자동으로 저장을 트리거","개발 경험의 연속성을 유지"]},"keywords":{"zh":["会话状态管理器","自动保存","Full-Stack开发","上下文丢失","开发体验","无缝开发","技术","自动触发","重要交互"],"ja":["セッションステートマネージャー","自動保存","Full-Stack開発","コンテキストの喪失","開発体験","シームレスな開発","技術","自動トリガー","重要なインタラクション"],"ko":["세션 상태 관리자","자동 저장","Full-Stack 개발","컨텍스트 손실","개발 경험","無中단 개발","기술","자동 트리거","중요한 상호작용"]}},"owner":"UBAIDRAZA1","repo":"UBAIDRAZA1-Todo-Web-Application","repoPath":"UBAIDRAZA1/UBAIDRAZA1-Todo-Web-Application","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.536Z","topics":[],"category":"community","skillMd":{"name":"session-state-manager","description":"Persistently stores conversation state, decisions, and progress to allow seamless resume across sessions.","bodyPreview":"# Session State Manager\n\n## Purpose\nThis skill prevents loss of context across sessions, restarts, or Claude limits by automatically saving state after every significant interaction.\n\n## What to Persist\nPersist continuously:\n- Last completed phase\n- Current active phase\n- Decisions made\n- Approved specs\n- Pending tasks\n- Last user instruction\n- Next recommended action\n- Files created/modified\n- Commands executed\n- Current branch\n\n## Auto-Save Triggers (MANDATORY)\nAutomatically save state after:","body":"# Session State Manager\n\n## Purpose\nThis skill prevents loss of context across sessions, restarts, or Claude limits by automatically saving state after every significant interaction.\n\n## What to Persist\nPersist continuously:\n- Last completed phase\n- Current active phase\n- Decisions made\n- Approved specs\n- Pending tasks\n- Last user instruction\n- Next recommended action\n- Files created/modified\n- Commands executed\n- Current branch\n\n## Auto-Save Triggers (MANDATORY)\nAutomatically save state after:\n1. **Every user message** - Update last instruction\n2. **File creation/modification** - Log changed files\n3. **Phase completion** - Mark phase as done\n4. **Skill execution** (/sp.specify, /sp.plan, /sp.tasks, /sp.implement)\n5. **Git operations** - Track branch and commits\n6. **Major decisions** - Document choices made\n\n## Save Strategy\n- **Append-only log** at `.claude/state/session.md`\n- **Timestamped entries** (ISO 8601 format)\n- **Structured format**:\n  ```markdown\n  ## [TIMESTAMP] - [ACTION]\n  - Phase: [Current Phase]\n  - Status: [Status Message]\n  - Files: [Modified Files]\n  - Next: [Next Action]\n  ---\n  ```\n- **Minimal but sufficient context** - No huge dumps\n\n## Load Strategy (MANDATORY)\nAt session start or when user says \"resume\":\n1. Check `.claude/state/session.md`\n2. Load last known state (most recent entry)\n3. Resume from exact stopping point\n4. Briefly summarize:\n   \"Resuming from Phase X, step Y - Last action: Z\"\n5. Continue seamlessly\n\n## Implementation (Auto-Execute)\nAfter EVERY significant action, append to `.claude/state/session.md`:\n\n```markdown\n## [ISO-TIMESTAMP] - [Brief Action Description]\n- **Phase**: Phase I - Python Console App (or current phase)\n- **Status**: [What was just completed]\n- **Branch**: [Current git branch]\n- **Files Modified**: [List of files]\n- **User Instruction**: \"[Last thing user said]\"\n- **Next Action**: [What should happen next]\n---\n```\n\n**Example Entry**:\n```markdown\n## 2025-12-27T15:30:00Z - Interactive CLI Created\n- **Phase**: Phase I - Python Console App\n- **Status**: Added colorful interactive menu with ANSI colors\n- **Branch**: 001-console-todo\n- **Files Modified**: src/todo_app/interactive.py, src/todo_app/__main__.py\n- **User Instruction**: \"mughy colorful cli chahiye\"\n- **Next Action**: Test interactive CLI and update session state\n---\n```\n\n## Safety Rules\n- Never hallucinate missing state\n- If state file missing, create fresh with current state\n- Never overwrite state history (append-only)\n- Keep entries concise (max 10 lines per entry)\n- Rotate file if > 1000 lines (move to session-archive.md)\n\n## Auto-Execution Rule (CRITICAL)\nThis skill should run **automatically** without user asking:\n- After every `/sp.*` skill completion\n- After file modifications (Write, Edit tools)\n- After user provides new instruction\n- Before responding to \"resume\" command\n\n**DO NOT wait for user to say \"/session\" - AUTO-SAVE ALWAYS!**\n\nThis skill ensures continuity and fast recovery.\n"},"lastSynced":"2026-02-18T15:59:18.853Z","qualityScore":50}');
